import { WorkerEntrypoint } from "cloudflare:workers";
// @ts-ignore -- generated by OpenNext, absent before the build
import handler from "../../.open-next/worker.js";
import { coreQuery, coreBlob, sandbox, type CoreEnv } from "./core";
import type { Statement } from "./gateway";

/** Preview capabilities have no public route and can never select the production DB. */
export class PreviewCore extends WorkerEntrypoint<CoreEnv> {
  query(tenant: string, statements: Statement[], batch: boolean) {
    return coreQuery(this.env, tenant, statements, batch);
  }
  blob(
    tenant: string,
    op: "get" | "put" | "delete",
    key: string,
    value?: ArrayBuffer,
    options?: unknown,
  ) {
    return coreBlob(this.env, tenant, op, key, value, options);
  }
  proxy(tenant: string, req: Request): Promise<Response> {
    const { db, blobs } = sandbox(this.env, tenant);
    if (
      !this.env.CORE_ORIGIN ||
      new URL(req.url).origin !== this.env.CORE_ORIGIN ||
      !new URL(req.url).pathname.startsWith("/api/") ||
      new URL(req.url).pathname.startsWith("/api/auth")
    )
      return Promise.resolve(new Response("Preview origin or path refused", { status: 403 }));
    // The dedicated Core isolate has its own AUTH_SECRET and baseURL. No global
    // auth/cache instance is shared with the production Worker or another tenant.
    return handler.fetch(req, { ...this.env, DB: db, BLOBS: blobs }, this.ctx);
  }
}
